DELIMITER $$
CREATE TRIGGER out_stock_guard BEFORE INSERT ON Out_stock FOR EACH ROW BEGIN IF NEW.amount>(SELECT amount FROM Stock WHERE mat_num=NEW.mat_num) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='领取量超过库存'; END IF; END$$
DELIMITER ;

DELIMITER $$
CREATE TRIGGER refresh_prj_cost AFTER UPDATE ON Out_stock FOR EACH ROW
BEGIN
 IF NOT (OLD.amount <=> NEW.amount) THEN
  INSERT INTO Prj_cost(prj_num,cost) SELECT NEW.prj_num,COALESCE(SUM(o.amount*s.unit),0) FROM Out_stock o JOIN Stock s USING(mat_num) WHERE o.prj_num=NEW.prj_num ON DUPLICATE KEY UPDATE cost=COALESCE((SELECT SUM(o.amount*s.unit) FROM Out_stock o JOIN Stock s USING(mat_num) WHERE o.prj_num=NEW.prj_num),0);
 END IF;
END$$
DELIMITER ;
